(function(global){
'use strict';
const auto=global.PoolShedAutomationCommand;if(!auto)return;
const pages=['Overview','Active Automations','Suggested Automations','Automation Builder','Templates','Alerts & Escalations','Approvals','Scheduled Jobs','Azzy','Activity Log'];
let page='Overview',draft=null;
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function notify(m){try{if(typeof toast==='function')toast(m);else console.log(m);}catch(_){console.log(m);}}
function renderNow(){try{if(typeof render==='function')render();else renderAutomationCommand();}catch(_){renderAutomationCommand();}}
function btn(label,action,cls,attrs){return '<button type="button" class="az-btn '+(cls||'')+'" data-az-action="'+action+'" '+(attrs||'')+'>'+esc(label)+'</button>';}
function pill(t,c){return '<span class="az-pill '+(c||'')+'">'+esc(t)+'</span>';}
function layout(title,subtitle,content,actions){return '<section class="automation-command"><header class="automation-head"><div><span class="automation-eyebrow">AUTOMATION COMMAND</span><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div><div class="automation-head-actions">'+(actions||'')+'</div></header><div class="automation-body">'+content+'</div></section>';}
function openAzzy(){const a=global.PoolShedAzzyJarvis;if(a&&typeof a.open==='function')return a.open();notify('Azzy is still starting. Try again in a moment.');}
function overview(){const s=auto.summary(),sugs=auto.suggested();return layout('Automation Command','Useful automations, approvals and Azzy guidance without losing control.','<div class="automation-metrics"><button data-az-page="Active Automations"><span>Active</span><strong>'+s.active+'</strong><small>Running governed workflows</small></button><button data-az-page="Suggested Automations"><span>Suggested</span><strong>'+s.suggestions+'</strong><small>Review before creating</small></button><button data-az-page="Approvals"><span>Awaiting approval</span><strong>'+s.approvals+'</strong><small>Controlled actions</small></button><button data-az-page="Activity Log"><span>Runs & activity</span><strong>'+s.runs+'</strong><small>Audited automation activity</small></button></div><div class="automation-grid"><section class="az-panel"><div class="az-panel-head"><div><h3>Suggested Automations</h3><p>Pool Shed notices repetitive or exception-based work. Nothing is switched on without review.</p></div>'+btn('View all','open-suggestions')+'</div>'+sugs.slice(0,4).map(x=>'<article class="az-suggestion"><div>'+pill(x.authority,x.authority==='Automatic'?'good':'warn')+'<h4>'+esc(x.name)+'</h4><p>'+esc(x.reason)+'</p></div>'+btn('Review workflow','use-template','','data-az-template="'+esc(x.templateId)+'"')+'</article>').join('')+'</section><aside><section class="az-panel"><div class="az-panel-head"><h3>Azzy</h3>'+pill('Pool Shed only','blue')+'</div><p>Ask Azzy about products, orders, projects, suppliers, stock, purchasing and authorised finance information. Azzy uses the signed-in user\'s Pool Shed access.</p>'+btn('Open Azzy','open-assistant','primary')+'</section><section class="az-panel"><div class="az-panel-head"><h3>Automation safety</h3></div><div class="az-safety"><b>Automatic</b><p>Low-risk internal alerts and reviews.</p><b>Approval Required</b><p>Prepared communications, POs, claims and transfers.</p><b>Suggest Only</b><p>Financial or commercial policy decisions.</p></div></section></aside></div>',btn('+ Build Automation','builder','primary')+btn('Templates','templates'));}
function activeAutomations(){const rules=auto.command().rules;return layout('Active Automations','See exactly what is running, why and under what authority.',rules.length?'<div class="az-table"><table><thead><tr><th>Workflow</th><th>Status</th><th>Authority</th><th>Steps</th><th>Updated</th><th></th></tr></thead><tbody>'+rules.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong><small>'+esc(r.id)+'</small></td><td>'+pill(r.status,r.status==='Active'?'good':'')+'</td><td>'+esc(r.authority||'Approval Required')+'</td><td>'+((r.nodes||[]).length)+'</td><td>'+esc((r.updatedAt||'').slice(0,16).replace('T',' '))+'</td><td>'+btn('Open','open-rule','mini','data-az-rule="'+esc(r.id)+'"')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="az-empty">No workflows have been saved yet. Start from a template or build one.</div>',btn('+ Build Automation','builder','primary'));}
function suggestions(){return layout('Suggested Automations','Recommendations based on useful Pool Shed operational patterns. Suggestions never activate themselves.',auto.suggested().map(x=>'<article class="az-suggestion large"><div>'+pill(x.authority,x.authority==='Automatic'?'good':'warn')+'<h3>'+esc(x.name)+'</h3><p>'+esc(x.reason)+'</p></div><div>'+btn('Use Template','use-template','primary','data-az-template="'+esc(x.templateId)+'"')+btn('Dismiss','dismiss-suggestion','')+'</div></article>').join(''),btn('Automation Templates','templates'));}
function nodeHtml(n,i){const cfg=n.config||{},detail=cfg.event||cfg.source||cfg.condition||cfg.action||cfg.duration||cfg.target||cfg.field||cfg.role||'Configure this step';return '<div class="flow-node '+normClass(n.type)+'" data-az-action="edit-node" data-az-node="'+i+'"><span class="flow-node-type">'+esc(n.type)+'</span><strong>'+esc(detail)+'</strong><small>Click to configure</small></div>'+(i<(draft.nodes||[]).length-1?'<div class="flow-connector"><span>↓</span><button data-az-action="insert-node" data-az-node="'+i+'">+</button></div>':'');}
function normClass(x){return String(x||'').toLowerCase().replace(/\s+/g,'-');}
function builder(){if(!draft){const t=auto.templates()[0];draft={id:'AUTO-'+Date.now(),name:t.name,authority:t.authority,status:'Draft',templateId:t.id,nodes:JSON.parse(JSON.stringify(t.nodes))};}const valid=auto.validate(draft);return layout('Automation Builder','Create governed Pool Shed workflows. Azzy is available separately for conversational help and operational intelligence.','<div class="flow-builder-toolbar"><label>Workflow name<input id="azFlowName" value="'+esc(draft.name)+'"></label><label>Authority<select id="azFlowAuthority"><option'+(draft.authority==='Automatic'?' selected':'')+'>Automatic</option><option'+(draft.authority==='Approval Required'?' selected':'')+'>Approval Required</option><option'+(draft.authority==='Suggest Only'?' selected':'')+'>Suggest Only</option></select></label>'+btn('Save Draft','save-flow')+btn('Test Workflow','test-flow','primary')+btn('Activate','activate-flow','success')+'</div><section class="az-panel build-with"><div><h3>Need help shaping the workflow?</h3><p>Describe it here for a safe template draft, or open Azzy to discuss the business context first.</p></div><div class="az-inline"><input id="azBuildPrompt" placeholder="When a customer invoice is 7 days overdue, check credits then create a chase..."><button data-az-action="build-natural">Build Draft</button>'+btn('Open Azzy','open-assistant')+'</div></section><div class="flow-layout"><aside class="flow-palette"><h3>Add step</h3>'+auto.nodeTypes().map(t=>'<button data-az-action="add-node" data-az-node-type="'+esc(t)+'"><b>'+esc(t)+'</b><small>'+nodeHint(t)+'</small></button>').join('')+'</aside><main class="flow-canvas"><div class="flow-canvas-head"><div><span>WORKFLOW CANVAS</span><h3>'+esc(draft.name)+'</h3></div>'+pill(valid.ok?'Valid':'Needs attention',valid.ok?'good':'bad')+'</div>'+(!valid.ok?'<div class="az-callout danger">'+valid.errors.map(esc).join('<br>')+'</div>':'')+'<div class="flow-stack">'+(draft.nodes||[]).map(nodeHtml).join('')+'</div></main><aside class="flow-inspector"><h3>Guardrails</h3><p><b>Pool Shed permissions apply.</b> Automation cannot bypass access controls.</p><p>Sensitive finance and commercial decisions remain Approval Required or Suggest Only.</p><p>Use <b>Test Workflow</b> before activation. Simulation makes no live changes.</p></aside></div>');}
function nodeHint(t){return ({Trigger:'Something happened',Schedule:'Run at a planned time',Condition:'Check a rule','Get Data':'Load a related record',Branch:'Yes / No path',Wait:'Pause until a time/date',Action:'Prepare or perform work',Approval:'Human decision gate',Notify:'Internal notification'})[t]||'';}
function templates(){return layout('Automation Templates','Start with a proven Pool Shed workflow, then change thresholds and actions before activation.','<div class="template-grid">'+auto.templates().map(t=>'<article><div>'+pill(t.authority,t.authority==='Automatic'?'good':'warn')+'<h3>'+esc(t.name)+'</h3><p>'+t.nodes.map(n=>n.type).join(' → ')+'</p></div>'+btn('Use Template','use-template','primary','data-az-template="'+esc(t.id)+'"')+'</article>').join('')+'</div>');}
function alerts(){const items=auto.suggested();return layout('Alerts & Escalations','Operational exceptions that automations can monitor, escalate or route for approval.','<div class="az-list">'+items.map((x,i)=>'<article><span class="az-alert-dot '+(i<2?'red':'amber')+'"></span><div><b>'+esc(x.name)+'</b><p>'+esc(x.reason)+'</p></div>'+btn('Build control','use-template','','data-az-template="'+esc(x.templateId)+'"')+'</article>').join('')+'</div>');}
function approvals(){const a=auto.command().approvals;return layout('Approvals','Sensitive automation actions wait here for a permitted person.',a.length?a.map(x=>'<article class="az-suggestion"><div><h4>'+esc(x.title||x.action||x.id)+'</h4><p>'+esc(x.reason||'Automation approval required.')+'</p></div>'+btn('Approve','approve','success','data-az-approval="'+esc(x.id)+'"')+btn('Reject','reject','danger','data-az-approval="'+esc(x.id)+'"')+'</article>').join(''):'<div class="az-empty">No automation approvals are waiting.</div>');}
function scheduled(){const jobs=auto.command().scheduledJobs;const defaults=[['Daily management brief','Every weekday · 07:30'],['Credit-control review','Daily · 08:00'],['Supplier promise review','Daily · 09:00'],['Engineer van stock review','Monday · 08:00'],['Invoice-ready sweep','Daily · 16:30']];return layout('Scheduled Jobs','Planned checks and briefings. Scheduled jobs still respect their workflow authority.',(jobs.length?jobs:defaults.map((x,i)=>({id:'JOB'+i,name:x[0],schedule:x[1],status:'Suggested'}))).map(j=>'<article class="az-job"><div><strong>'+esc(j.name)+'</strong><small>'+esc(j.schedule)+'</small></div>'+pill(j.status||'Active',(j.status||'')==='Active'?'good':'')+'</article>').join(''));}
function azzyPage(){return layout('Azzy','The finished Pool Shed intelligence assistant is available globally.','<div class="automation-grid"><section class="az-panel"><div class="az-panel-head"><div><h3>One Azzy, everywhere</h3><p>Azzy uses the signed-in user, current Pool Shed records and the active page context. There is no second assistant or legacy Ask / Find / Guide interface behind this page.</p></div>'+pill('Pool Shed only','blue')+'</div><p>Use Azzy for project comparisons, stock and product questions, purchasing demand, supplier comparisons, warehouse work, bills, attention items and controlled action proposals.</p>'+btn('Open Azzy','open-assistant','primary')+'</section><section class="az-panel"><div class="az-panel-head"><h3>Safety contract</h3></div><div class="az-safety"><b>Permission first</b><p>Azzy only receives records the signed-in user is allowed to see.</p><b>Human approval</b><p>Controlled writes remain approval-gated and execute through Pool Shed authorities.</p><b>Pool Shed only</b><p>Operational facts are grounded in the app, not silently outsourced.</p></div></section></div>');}
function activity(){const runs=auto.command().runs.slice().reverse();return layout('Activity Log','What ran, who approved it, what happened and why.',runs.length?'<div class="az-table"><table><thead><tr><th>Date</th><th>Workflow</th><th>Type</th><th>Result</th><th>User</th></tr></thead><tbody>'+runs.map(r=>'<tr><td>'+esc((r.createdAt||'').slice(0,16).replace('T',' '))+'</td><td>'+esc(r.ruleId)+'</td><td>'+esc(r.type)+'</td><td>'+esc(r.result)+'</td><td>'+esc(r.user)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="az-empty">No automation activity has been recorded yet.</div>');}
function renderAutomationCommand(){const screen=document.getElementById('screen-automation');if(!screen)return;if(typeof activeSubPage!=='undefined'&&activeSubPage.automation&&pages.includes(activeSubPage.automation))page=activeSubPage.automation;const map={'Overview':overview,'Active Automations':activeAutomations,'Suggested Automations':suggestions,'Automation Builder':builder,'Templates':templates,'Alerts & Escalations':alerts,'Approvals':approvals,'Scheduled Jobs':scheduled,'Azzy':azzyPage,'Activity Log':activity};screen.innerHTML=(map[page]||overview)();}
function setPage(p){page=pages.includes(p)?p:'Overview';if(typeof activeSubPage!=='undefined')activeSubPage.automation=page;renderNow();}
function modal(title,body,footer){let root=document.getElementById('azModal');if(root)root.remove();root=document.createElement('div');root.id='azModal';root.className='az-modal-wrap';root.innerHTML='<div class="az-modal"><header><h3>'+esc(title)+'</h3>'+btn('Close','close-modal','mini')+'</header><div class="az-modal-body">'+body+'</div><footer>'+(footer||'')+'</footer></div>';document.body.appendChild(root);}
function useTemplate(id){const t=auto.templates().find(x=>x.id===id);if(!t)return;draft={id:'AUTO-'+Date.now(),name:t.name,authority:t.authority,status:'Draft',templateId:t.id,nodes:JSON.parse(JSON.stringify(t.nodes))};setPage('Automation Builder');}
function naturalFlow(text){const q=String(text||'').toLowerCase();let t=q.includes('supplier')||q.includes('po')?auto.templates().find(x=>x.id==='late-supplier-po'):q.includes('invoice')||q.includes('customer')?auto.templates().find(x=>x.id==='overdue-customer-invoice'):auto.templates()[0];draft={id:'AUTO-'+Date.now(),name:t.name,authority:t.authority,status:'Draft',templateId:t.id,nodes:JSON.parse(JSON.stringify(t.nodes)),createdFromPrompt:String(text||'')};notify('Draft workflow created from your description. Review every step before activation.');renderNow();}
function settingsData(){return '<section class="assistant-settings"><div class="settings-grid two"><section class="az-panel"><div class="az-panel-head"><h3>Azzy</h3>'+pill('Pool Shed only','blue')+'</div><p>Azzy is the single global assistant. Its visual identity and conversational experience are maintained by the Jarvis interface rather than a second settings-only assistant profile.</p>'+btn('Open Azzy','open-assistant','primary')+'</section><section class="az-panel"><h3>Permission contract</h3><p>Pool Shed authentication, role permissions, financial visibility, location scope, approval limits and audit authority remain the source of truth.</p></section></div></section>';}
const legacySettings=typeof global.renderSettings==='function'?global.renderSettings:null;if(legacySettings){global.renderSettings=function(){if(typeof selectedSubPage==='function'&&selectedSubPage('settings')==='Assistant & Automation'){const s=document.getElementById('screen-settings');if(s)s.innerHTML=settingsData();return;}return legacySettings();};}
const legacyGroups=typeof global.sidebarSubGroups==='function'?global.sidebarSubGroups:null;if(legacyGroups){global.sidebarSubGroups=function(id){if(id==='automation')return pages;if(id==='settings'){const g=legacyGroups(id).slice();if(!g.includes('Assistant & Automation'))g.splice(Math.min(9,g.length),0,'Assistant & Automation');return g;}return legacyGroups(id);};}
const legacyOpen=typeof global.openSidebarSubGroup==='function'?global.openSidebarSubGroup:null;if(legacyOpen){global.openSidebarSubGroup=function(tabId,sub){if(tabId==='automation'){active='automation';setPage(sub);return;}return legacyOpen(tabId,sub);};}
function handle(action,el){if(action==='open-assistant')return openAzzy();if(action==='open-suggestions')return setPage('Suggested Automations');if(action==='builder')return setPage('Automation Builder');if(action==='templates')return setPage('Templates');if(action==='use-template')return useTemplate(el.dataset.azTemplate);if(action==='save-flow'){draft.name=document.getElementById('azFlowName')?.value||draft.name;draft.authority=document.getElementById('azFlowAuthority')?.value||draft.authority;auto.saveRule(draft);notify('Automation draft saved.');return renderNow();}if(action==='test-flow'){draft.name=document.getElementById('azFlowName')?.value||draft.name;draft.authority=document.getElementById('azFlowAuthority')?.value||draft.authority;const sim=auto.simulate(draft,null);modal('Test Workflow','<div class="az-callout good"><b>No live changes made</b><p>Simulation checked '+sim.steps.length+' workflow steps.</p></div>'+sim.steps.map(s=>'<div class="simulation-step">'+pill(s.status,s.status==='pending-approval'?'warn':'good')+'<b>'+esc(s.type)+'</b><small>'+esc(s.detail)+'</small></div>').join(''),btn('Mark Test Passed','mark-test-passed','primary'));return;}if(action==='mark-test-passed'){draft._simulationPassed=true;document.getElementById('azModal')?.remove();notify('Workflow simulation passed. Review then activate.');return;}if(action==='activate-flow'){const saved=auto.saveRule(draft),res=auto.activateRule(saved.id,{simulationPassed:!!draft._simulationPassed});if(!res.ok)return notify(res.reason);notify('Workflow activated with audit record.');return setPage('Active Automations');}if(action==='add-node'){draft.nodes.push({type:el.dataset.azNodeType,config:{}});return renderNow();}if(action==='insert-node'){draft.nodes.splice(Number(el.dataset.azNode)+1,0,{type:'Condition',config:{field:'',operator:'=',value:''}});return renderNow();}if(action==='edit-node'){const i=Number(el.dataset.azNode),n=draft.nodes[i],cfg=n.config||{};modal('Configure '+n.type,'<label class="az-field">Description / setting<input id="azNodeValue" value="'+esc(cfg.action||cfg.event||cfg.source||cfg.duration||cfg.target||cfg.field||cfg.role||'')+'"></label>',btn('Save Step','save-node','primary','data-az-node="'+i+'"')+btn('Delete Step','delete-node','danger','data-az-node="'+i+'"'));return;}if(action==='save-node'){const i=Number(el.dataset.azNode),n=draft.nodes[i],v=document.getElementById('azNodeValue').value;n.config=n.config||{};if(n.type==='Action')n.config.action=v;else if(n.type==='Trigger'||n.type==='Schedule')n.config.event=v;else if(n.type==='Get Data')n.config.source=v;else if(n.type==='Wait')n.config.duration=v;else if(n.type==='Notify')n.config.target=v;else if(n.type==='Approval')n.config.role=v;else n.config.field=v;document.getElementById('azModal')?.remove();return renderNow();}if(action==='delete-node'){draft.nodes.splice(Number(el.dataset.azNode),1);document.getElementById('azModal')?.remove();return renderNow();}if(action==='build-natural')return naturalFlow(document.getElementById('azBuildPrompt')?.value);if(action==='close-modal'){document.getElementById('azModal')?.remove();return;}if(action==='open-rule'){const r=auto.command().rules.find(x=>x.id===el.dataset.azRule);if(r){draft=JSON.parse(JSON.stringify(r));return setPage('Automation Builder');}}if(action==='dismiss-suggestion')return notify('Suggestion dismissed for this review.');notify('Action recorded.');}
document.addEventListener('click',e=>{const p=e.target.closest&&e.target.closest('[data-az-page]');if(p){e.preventDefault();return setPage(p.dataset.azPage);}const el=e.target.closest&&e.target.closest('[data-az-action]');if(el){e.preventDefault();return handle(el.dataset.azAction,el);}});
global.renderAutomation=renderAutomationCommand;global.PoolShedAutomationWorkspace={pages,render:renderAutomationCommand,setPage,openAssistant:openAzzy,renderSettingsPanel:settingsData};
})(typeof globalThis!=='undefined'?globalThis:window);
